import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Mail, Lock, Chrome, UserPlus } from 'lucide-react';

const Home = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const navigate = useNavigate();

  const handleLogin = (e) => {
    e.preventDefault();
    // Logic for login goes here
    console.log("Logging in with:", email, password);
  };

  return (
    <div className="min-h-screen bg-[#f3f4f9] flex flex-col font-sans relative">
      
      {/* Top Right Register Button */}
      <div className="absolute top-6 right-8">
        <button 
          onClick={() => navigate('/register')}
          className="flex items-center gap-2 bg-white text-[#7c5dfa] border border-[#7c5dfa] px-5 py-2 rounded-full font-semibold hover:bg-[#7c5dfa] hover:text-white transition-all shadow-sm"
        >
          <UserPlus size={18} />
          Register
        </button>
      </div>

      {/* Main Login Card Container */}
      <div className="flex-grow flex items-center justify-center">
        <div className="bg-white p-10 rounded-3xl shadow-xl w-full max-w-md border border-gray-100">
          
          {/* Header */}
          <div className="text-center mb-10">
            <div className="inline-block bg-purple-100 p-4 rounded-2xl mb-4">
              <div className="bg-[#7c5dfa] w-10 h-10 rounded-lg flex items-center justify-center">
                <Lock className="text-white" size={20} />
              </div>
            </div>
            <h1 className="text-2xl font-bold text-gray-800">Talent Pool Portal</h1>
            <p className="text-gray-400 text-sm mt-1">Please enter your details to sign in</p>
          </div>

          <form onSubmit={handleLogin} className="space-y-5">
            {/* Email Field */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Email Address</label>
              <div className="relative">
                <Mail className="absolute left-3 top-3.5 text-gray-400" size={18} />
                <input 
                  type="email" 
                  placeholder="name@company.com"
                  className="w-full pl-10 pr-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-purple-400 focus:bg-white outline-none transition-all"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  required
                />
              </div>
            </div>

            {/* Password Field */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Password</label>
              <div className="relative">
                <Lock className="absolute left-3 top-3.5 text-gray-400" size={18} />
                <input 
                  type="password" 
                  placeholder="••••••••"
                  className="w-full pl-10 pr-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-purple-400 focus:bg-white outline-none transition-all"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  required
                />
              </div>
            </div>

            {/* Login Button */}
            <button 
              type="submit"
              className="w-full bg-[#7c5dfa] hover:bg-[#6a4dec] text-white font-bold py-3.5 rounded-xl shadow-lg transition-all active:scale-[0.98]"
            >
              Login
            </button>
          </form>

          {/* Divider */}
          <div className="flex items-center my-8">
            <div className="flex-grow border-t border-gray-100"></div>
            <span className="px-4 text-gray-400 text-xs font-medium uppercase tracking-widest">Or</span>
            <div className="flex-grow border-t border-gray-100"></div>
          </div>

          {/* Google Sign In */}
          <button className="w-full flex items-center justify-center gap-3 border border-gray-200 py-3.5 rounded-xl hover:bg-gray-50 transition-all text-gray-600 font-semibold">
            <Chrome size={20} className="text-red-500" />
            Sign in with Google
          </button>
        </div>
      </div>
    </div>
  );
};

export default Home;
